//! The boundary between the host and a renderer in another process (the Ink
//! renderer, `ink/`): versioned, bounded messages, one JSON object per
//! newline-terminated UTF-8 line over a Unix domain socket. The renderer
//! learns everything it shows from these messages and sends back only what
//! the user did ([`Intent`]); the host keeps the parts, the mode and
//! permission checks, confirmations and the journal.
//!
//! The TypeScript side of these types is generated by ts-rs into
//! `ink/src/protocol/generated/`; a test fails when the committed files
//! differ from a fresh export (`RADAR_TS_UPDATE=1` writes them).

use serde::{Deserialize, Serialize};
use ts_rs::TS;

use crate::view::{ChromeView, Intent, MenuView, PaneId, ScreenView, SectionView};
pub use crate::motion::transition::{MotionContext, MotionFold, MotionInteraction};

/// The protocol's version. Bumped on any change either side could misread;
/// a renderer that says another is refused ([`ToRenderer::Refuse`]).
pub const PROTOCOL: u32 = 1;

/// The longest line either side sends or accepts, in bytes. A longer line
/// closes the connection: nothing in the protocol needs more.
pub const MAX_LINE: usize = 16 * 1024 * 1024;

/// The longest [`ToHost::Log`] text the host keeps, in characters; the
/// rest is cut.
pub const MAX_LOG: usize = 2048;

/// The longest [`ToRenderer::Notice`] text, and an [`InputRequest`]'s
/// title, in characters; the host cuts the rest.
pub const MAX_NOTICE: usize = 2048;

/// The longest text an [`InputRequest`] starts with, in characters.
pub const MAX_INPUT: usize = 64 * 1024;

/// The most text one [`ToRenderer::Clipboard`] carries, in bytes.
pub const MAX_CLIPBOARD: usize = 1024 * 1024;

/// Which renderer draws the TUI. `RADAR_RENDERER=ink|ratatui` overrides the
/// build's default (`radar::DEFAULT_RENDERER`); there is no other switch.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Renderer {
    Ratatui,
    Ink,
}

impl Renderer {
    /// The renderer `RADAR_RENDERER` names, else `default`. An unknown value
    /// is not guessed at: the default runs.
    pub fn chosen(default: Renderer, var: Option<&str>) -> Renderer {
        match var.map(str::trim) {
            Some("ink") => Renderer::Ink,
            Some("ratatui") => Renderer::Ratatui,
            _ => default,
        }
    }
}

/// The graphics protocol the renderer's terminal draws pictures with.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum ImageProtocol {
    Kitty,
    Sixel,
    None,
}

/// What the renderer's terminal can do, as the renderer found out.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct Capabilities {
    pub columns: u16,
    pub rows: u16,
    /// It reports the mouse (and the renderer asked for it).
    pub mouse: bool,
    pub true_colour: bool,
    pub image: ImageProtocol,
    /// Labelled lines in reading order, no layout (accessibility).
    pub plain_text: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum LogLevel {
    Debug,
    Info,
    Warn,
    Error,
}

/// Renderer → host.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ToHost {
    /// The first message: the protocol it speaks and its terminal.
    Hello {
        protocol: u32,
        /// The view contract it reads ([`crate::view::VERSION`]).
        view: u32,
        capabilities: Capabilities,
    },
    /// The terminal changed size.
    Resize { columns: u16, rows: u16 },
    /// What the user did, at the snapshot it was seen on.
    Intent {
        /// The renderer's own count, from 1, so a log names each.
        #[ts(type = "number")]
        seq: u64,
        /// The cursor of the snapshot showing when the user acted.
        #[ts(type = "number")]
        cursor: u64,
        intent: Intent,
    },
    /// The cell the pointer pressed, sent just before the `intent` it
    /// belongs to. A `context` intent that opens a menu opens it there, as
    /// the Ratatui runner opens one at a right-click; any other intent
    /// forgets it.
    Pointer { column: u16, row: u16 },
    /// The snapshot with this cursor is drawn; the next may come.
    Ack {
        #[ts(type = "number")]
        cursor: u64,
    },
    /// A line for radar's log: what happened, never what was shown.
    Log { level: LogLevel, text: String },
    /// The renderer is leaving (the user quit through it).
    Bye,
    /// The dock's transcript came as a change to a revision the renderer
    /// does not hold ([`crate::dock::DockView::kept`]): the next snapshot
    /// sends it whole.
    Resync,
}

/// What is showing, whole: the newest replaces any not yet sent.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct Snapshot {
    /// Rises by one per state the host sends; never reused in a session.
    #[ts(type = "number")]
    pub cursor: u64,
    /// The top bar, status line, the open menu or question, notices and
    /// settings navigation.
    pub chrome: ChromeView,
    /// The screen showing, when one is (not while settings show).
    pub screen: Option<ScreenView>,
    /// The settings section showing, when settings show.
    pub section: Option<SectionView>,
    /// The agent dock while settings show (a screen carries its own), so a
    /// sign-in started in Settings runs in a tab drawn under the section.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub dock: Option<Box<crate::dock::DockView>>,
    /// The pane the keys go to.
    pub focus: PaneId,
    /// Motion: the level, the cues raised since the last snapshot sent,
    /// and what the effects need.
    #[serde(default)]
    pub motion: MotionView,
    /// The startup splash while it shows: drawn over everything, cell for
    /// cell as the Ratatui runner paints it ([`crate::splash`]). Keys and
    /// clicks still go to the screen under it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub splash: Option<crate::splash::SplashView>,
    /// With `RADAR_TRACE_LATENCY=1` only: what this snapshot answers and how
    /// long the host took, so the renderer can log the whole way from a key
    /// or an agent's words to the frame painted. Absent otherwise.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub trace: Option<SnapshotTrace>,
}

/// What a snapshot answers, for latency tracing (`RADAR_TRACE_LATENCY=1`).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct SnapshotTrace {
    /// The oldest change it shows: `intent dock send`, `intent key`,
    /// `event wake` (an agent's output), `event tick`, `event msg`, or
    /// `session ready (...)` (a session started
    /// earlier can now be written to).
    pub cause: String,
    /// The newest renderer intent (its `seq`) this snapshot answers.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional, type = "number")]
    pub seq: Option<u64>,
    /// When the cause reached the host, in ms since the Unix epoch.
    pub at_ms: f64,
    /// From the cause to the snapshot ready to send, in ms.
    pub host_ms: f64,
    /// The snapshot's size as sent, in bytes.
    #[ts(type = "number")]
    pub bytes: u64,
}

/// How much motion runs here (`[theme] motion`, held back over SSH and
/// where the terminal is not full colour), as [`crate::motion::Level`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum MotionLevel {
    Full,
    Subtle,
    #[default]
    Off,
}

impl From<crate::motion::Level> for MotionLevel {
    fn from(l: crate::motion::Level) -> Self {
        match l {
            crate::motion::Level::Full => Self::Full,
            crate::motion::Level::Subtle => Self::Subtle,
            crate::motion::Level::Off => Self::Off,
        }
    }
}

/// Where a cue's effect runs, as [`crate::motion::Region`]: the body
/// between the top bar and the status line, the menu or confirm on screen,
/// or the message on the status line.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum MotionRegion {
    Body,
    Popup,
    Message,
}

/// What happened that motion shows, as [`crate::motion::Cue`]. Only cues
/// that run at the snapshot's level are sent.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum MotionCue {
    /// Another screen: a fade of the body.
    Screen { region: MotionRegion },
    /// An item's page opened: a sweep over the body.
    Page { region: MotionRegion },
    /// A menu or a confirm appeared.
    Popup { region: MotionRegion },
    /// A message appeared on the status line.
    Message { region: MotionRegion },
    /// The message left: it fades out where it was.
    MessageGone { region: MotionRegion },
    /// A sync changed these rows (`changed`) or added them (`added`); the
    /// keys are the rows' `glow` keys in the views.
    Changed { changed: Vec<String>, added: Vec<String> },
}

/// How long each effect runs, in ms ([`crate::motion::SCREEN_MS`] …).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct MotionTimings {
    pub screen: u32,
    pub page: u32,
    pub popup: u32,
    pub message: u32,
    pub message_gone: u32,
    pub glow: u32,
    pub added: u32,
    /// One pass of the loading shimmer, repeated while a panel waits.
    pub shimmer: u32,
    /// How often to draw while an effect runs.
    pub frame: u32,
}

impl Default for MotionTimings {
    fn default() -> Self {
        use crate::motion as m;
        Self {
            screen: m::SCREEN_MS,
            page: m::PAGE_MS,
            popup: m::POPUP_MS,
            message: m::MESSAGE_MS,
            message_gone: m::MESSAGE_GONE_MS,
            glow: m::GLOW_MS,
            added: m::ADDED_MS,
            shimmer: m::SHIMMER_MS,
            frame: m::FRAME.as_millis() as u32,
        }
    }
}

/// The theme slots (names in [`Look::slots`]) the effects blend with, as
/// the Ratatui engine takes them: fades go to `base`, sweeps in over
/// `surface` or `overlay`, the glow is `glow`'s colour.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct MotionSlots {
    pub base: String,
    pub surface: String,
    pub overlay: String,
    pub glow: String,
    pub text: String,
}

impl Default for MotionSlots {
    fn default() -> Self {
        Self {
            base: "bg.base".into(),
            surface: "bg.surface".into(),
            overlay: "bg.overlay".into(),
            glow: "accent.primary".into(),
            text: "text.primary".into(),
        }
    }
}

/// Everything Ink needs to run radar's motion effects. Rows carry their
/// `glow` key and panels waiting for data their `loading` state in the
/// views themselves.
#[derive(Debug, Clone, PartialEq, Eq, Default, Serialize, Deserialize, TS)]
pub struct MotionView {
    pub level: MotionLevel,
    /// Optional full-motion interaction identity and causal acknowledgement.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub interaction: Option<MotionInteraction>,
    /// Why motion is off whatever the setting says (over SSH, not full
    /// colour), when it is.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub held_back: Option<String>,
    /// Raised since the last snapshot sent, oldest first.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub cues: Vec<MotionCue>,
    #[serde(default)]
    pub timings: MotionTimings,
    #[serde(default)]
    pub slots: MotionSlots,
}

/// A question or a menu the host is waiting on: sent once when it opens,
/// never coalesced, answered by an [`Intent::Invoke`] with a choice's value
/// (or [`Intent::Key`] Esc to close it).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct Question {
    /// Unique in the session.
    #[ts(type = "number")]
    pub id: u64,
    #[ts(type = "number")]
    pub cursor: u64,
    pub menu: MenuView,
}

/// Text the host is capturing (a menu's field): the renderer edits it and
/// sends the keys as [`Intent::Key`].
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct InputRequest {
    #[ts(type = "number")]
    pub id: u64,
    #[ts(type = "number")]
    pub cursor: u64,
    pub title: String,
    pub value: String,
}

/// A notice the user must see even when a later snapshot replaces it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct Notice {
    #[ts(type = "number")]
    pub cursor: u64,
    pub text: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub occurrence: Option<crate::view::chrome::NoticeView>,
    #[serde(default, skip_serializing_if = "notice_zero")]
    #[ts(type = "number")]
    pub revision: u64,
    #[serde(default, skip_serializing_if = "notice_zero")]
    #[ts(type = "number")]
    pub now_ms: u64,
}

fn notice_zero(value: &u64) -> bool { *value == 0 }

/// Host → renderer.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ToRenderer {
    /// The renderer is accepted; the first snapshot follows.
    Welcome {
        protocol: u32,
        view: u32,
        #[ts(type = "number")]
        cursor: u64,
    },
    /// The renderer speaks another protocol: it shows `message` and exits
    /// (code 3).
    Refuse {
        wanted: u32,
        got: u32,
        message: String,
    },
    /// The colours and icons to draw with, as the host resolved them: sent
    /// after [`ToRenderer::Welcome`] before the first snapshot, and again
    /// whenever the theme or icon configuration changes. Never coalesced
    /// away; the newest replaces the last.
    Look(Box<Look>),
    Snapshot(Box<Snapshot>),
    Question(Question),
    InputRequest(InputRequest),
    Notice(Notice),
    /// Put `text` on the terminal's clipboard (OSC 52): only the process
    /// that owns the terminal writes to it. At most [`MAX_CLIPBOARD`]
    /// bytes; the host says so instead of sending more.
    Clipboard { text: String },
    /// Leave: restore nothing (the host does), exit 0.
    Shutdown {
        reason: String,
    },
}

impl ToHost {
    /// Within the protocol's bounds: a log line is cut to [`MAX_LOG`].
    pub fn bounded(self) -> Self {
        match self {
            ToHost::Log { level, text } if text.chars().count() > MAX_LOG => ToHost::Log {
                level,
                text: text.chars().take(MAX_LOG).collect(),
            },
            other => other,
        }
    }
}

/// One message as its line: compact JSON and a newline.
pub fn encode<T: Serialize>(message: &T) -> Vec<u8> {
    let mut line = serde_json::to_vec(message).expect("protocol messages serialise");
    line.push(b'\n');
    line
}

/// Lines, reassembled from what arrives in pieces.
#[derive(Debug, Default)]
pub struct Lines {
    held: Vec<u8>,
}

/// A line over [`MAX_LINE`]: the connection closes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TooLong;

impl Lines {
    /// Add what arrived; every whole line in it comes back, without its
    /// newline.
    pub fn push(&mut self, bytes: &[u8]) -> Result<Vec<Vec<u8>>, TooLong> {
        let mut out = Vec::new();
        for &b in bytes {
            if b == b'\n' {
                out.push(std::mem::take(&mut self.held));
            } else {
                if self.held.len() >= MAX_LINE {
                    return Err(TooLong);
                }
                self.held.push(b);
            }
        }
        Ok(out)
    }
}

